@test("opening balance defaults to 0")
def _():
    assert BankAccount("Ana").balance == 0
    assert BankAccount("Ana", 100).balance == 100

@test("a negative opening balance raises ValueError")
def _():
    raises(ValueError, BankAccount, "Ana", -1)

@test("deposit and withdraw change the balance")
def _():
    a = BankAccount("Ana", 100)
    a.deposit(50)
    a.withdraw(30)
    assert a.balance == 120, f"balance is {a.balance}, expected 120"

@test("non-positive amounts raise ValueError")
def _():
    a = BankAccount("Ana", 100)
    for bad in (0, -5):
        raises(ValueError, a.deposit, bad)
        raises(ValueError, a.withdraw, bad)
    assert a.balance == 100

@test("overdrawing raises InsufficientFunds and leaves the balance alone")
def _():
    a = BankAccount("Ana", 40)
    e = raises(InsufficientFunds, a.withdraw, 100)
    assert isinstance(e, Exception)
    assert (e.requested, e.available) == (100, 40), f"requested/available = {(getattr(e, 'requested', None), getattr(e, 'available', None))}"
    assert a.balance == 40

@test("history records successful operations in order")
def _():
    a = BankAccount("Ana", 10)
    a.deposit(5)
    try:
        a.withdraw(1000)
    except InsufficientFunds:
        pass
    a.withdraw(3)
    assert a.history == [("deposit", 5), ("withdraw", 3)], f"history is {a.history}"

@test("history can't be modified from outside")
def _():
    a = BankAccount("Ana")
    a.deposit(5)
    a.history.append(("deposit", 1_000_000))
    a.history.clear()
    assert a.history == [("deposit", 5)], f"history is {a.history}"

@test("balance is read-only")
def _():
    a = BankAccount("Ana", 10)
    raises(AttributeError, setattr, a, "balance", 999)
    assert a.balance == 10

@test("repr shows owner and balance")
def _():
    a = BankAccount("Ana", 100)
    a.deposit(50)
    assert repr(a) == "BankAccount('Ana', 150)", f"repr is {a!r}"

